"""Copilot v2 auto-analysis of training and validation failures.

This module speaks the v1 payload vocabulary, not AG-UI, so the existing
job-events listener needs no change.

Customer logs and files reach the model as ``instructions``, so they carry
system authority. The agent's only tools are the read-only MCP allowlist below
and the native documentation search, which is read-only too, and guardrails
never run here. ``test_host_independence.py`` enforces that.

The job owner owns lifecycle events, persistence, and error reports.
"""

from __future__ import annotations

import importlib.resources
import uuid
from collections.abc import AsyncIterator

try:
    from pydantic_ai import Agent
    from pydantic_ai.mcp import MCPServerStreamableHTTP
    from pydantic_ai.messages import (
        FunctionToolCallEvent,
        FunctionToolResultEvent,
        PartDeltaEvent,
        PartStartEvent,
        TextPart,
        TextPartDelta,
        ToolReturnPart,
    )
    from pydantic_ai.tools import RunContext, ToolDefinition
    from pydantic_ai.usage import UsageLimits
except ImportError as exc:
    raise ImportError(
        "pydantic-ai-slim is required for Copilot v2. "
        "Install with: pip install rasa-pro[copilot-v2]"
    ) from exc

from rasa.builder.copilot.constants import (
    COPILOT_PROMPTS_DIR,
    COPILOT_TRAINING_ERROR_HANDLER_PROMPT_FILE_AGENT,
)
from rasa.builder.copilot.mcp_server.constants import (
    MCP_TOOL_GET_ASSISTANT_LOGS,
    MCP_TOOL_GET_DOMAIN_SCHEMA,
    MCP_TOOL_GET_E2E_SCHEMA,
    MCP_TOOL_GET_FLOW,
    MCP_TOOL_GET_FLOW_SCHEMA,
    MCP_TOOL_GET_RESPONSE,
    MCP_TOOL_GET_SLOT,
    MCP_TOOL_LIST_CUSTOM_ACTION_IMPLEMENTATIONS,
    MCP_TOOL_LIST_DEFAULT_ACTIONS,
    MCP_TOOL_LIST_DOMAIN_ACTIONS,
    MCP_TOOL_LIST_FLOWS,
    MCP_TOOL_LIST_RESPONSES,
    MCP_TOOL_LIST_SLOTS,
)
from rasa.builder.copilot.mcp_server.prompts.prompt_loader import copilot_jinja_env
from rasa.builder.copilot.models import (
    CopilotOutput,
    CopilotTextContent,
    CopilotTextEndContent,
    CopilotTextStartContent,
    FileContent,
    InternalCopilotRequestChatMessage,
    MCPToolCall,
    MCPToolCallStatus,
)
from rasa.builder.copilot.pydantic_ai.config import PydanticAIConfig
from rasa.builder.copilot.pydantic_ai.document_search import (
    register_document_search_tools,
)
from rasa.builder.copilot.pydantic_ai.instrumentation import build_instrumentation
from rasa.builder.copilot.pydantic_ai.prompt_loader import V2_SYSTEM_PROMPT
from rasa.builder.copilot.pydantic_ai.run_context import CopilotRunContext
from rasa.builder.copilot.pydantic_ai.types import RunRequest
from rasa.builder.telemetry.langfuse_integration.constants import (
    COPILOT_V2_ANALYSIS_AGENT_NAME,
)
from rasa.shared.constants import PACKAGE_NAME

ANALYSIS_USER_PROMPT = "Analyze the training failure using the provided logs and files."

READ_ONLY_MCP_TOOLS = frozenset(
    {
        MCP_TOOL_GET_ASSISTANT_LOGS,
        MCP_TOOL_LIST_CUSTOM_ACTION_IMPLEMENTATIONS,
        MCP_TOOL_LIST_FLOWS,
        MCP_TOOL_LIST_SLOTS,
        MCP_TOOL_LIST_RESPONSES,
        MCP_TOOL_LIST_DOMAIN_ACTIONS,
        MCP_TOOL_LIST_DEFAULT_ACTIONS,
        MCP_TOOL_GET_FLOW,
        MCP_TOOL_GET_SLOT,
        MCP_TOOL_GET_RESPONSE,
        MCP_TOOL_GET_FLOW_SCHEMA,
        MCP_TOOL_GET_DOMAIN_SCHEMA,
        MCP_TOOL_GET_E2E_SCHEMA,
    }
)


def render_training_error_prompt(message: InternalCopilotRequestChatMessage) -> str:
    """Render the v1 training-error template for one internal request."""
    template = copilot_jinja_env().from_string(
        importlib.resources.read_text(
            f"{PACKAGE_NAME}.{COPILOT_PROMPTS_DIR}",
            COPILOT_TRAINING_ERROR_HANDLER_PROMPT_FILE_AGENT,
        )
    )
    return template.render(
        logs=message.get_flattened_log_content(),
        modified_files={
            file.file_path: file.file_content
            for file in message.get_content_blocks_by_type(FileContent)
        },
    )


async def stream_training_error_analysis(
    message: InternalCopilotRequestChatMessage,
    config: PydanticAIConfig | None = None,
    *,
    project_path: str | None = None,
) -> AsyncIterator[CopilotOutput]:
    """Run the analysis on the PydanticAI runtime and stream v1 payloads.

    ``project_path`` picks the documentation corpus to search. ``None``
    searches the CALM v1 docs.

    Model and MCP failures propagate. The job owner reports them as
    ``copilot_analysis_error``.
    """
    config = config or PydanticAIConfig()
    agent = _build_analysis_agent(config, render_training_error_prompt(message))

    yield CopilotTextStartContent()
    async with agent.run_stream_events(
        ANALYSIS_USER_PROMPT,
        deps=_analysis_run_context(project_path),
        usage_limits=UsageLimits(request_limit=config.max_model_requests),
    ) as event_stream:
        async for event in event_stream:
            output = _map_runtime_event(event)
            if output is not None:
                yield output
    yield CopilotTextEndContent()


def _is_read_only_tool(_ctx: RunContext[None], tool_def: ToolDefinition) -> bool:
    return tool_def.name in READ_ONLY_MCP_TOOLS


def _build_analysis_agent(
    config: PydanticAIConfig, instructions: str
) -> Agent[CopilotRunContext, str]:
    server = MCPServerStreamableHTTP(config.mcp_url).filtered(_is_read_only_tool)
    # Only documentation search is engine-aware: it reads the run's
    # project_path to pick the Mantle or CALM v1 corpus. The prompt and the
    # read-only allowlist are still v1-shaped, and the MCP server hides those
    # tools for Mantle projects.
    agent: Agent[CopilotRunContext, str] = Agent(
        config.model_name,
        # Named so the agent-run span identifies which v2 agent produced it: at
        # the pinned instrumentation version the name reaches both the span name
        # and ``gen_ai.agent.name``.
        name=COPILOT_V2_ANALYSIS_AGENT_NAME,
        deps_type=CopilotRunContext,
        system_prompt=V2_SYSTEM_PROMPT,
        instructions=instructions,
        output_type=str,
        toolsets=[server],
        # Without this the analysis emits no spans at all — there is no global
        # ``Agent.instrument_all()`` anywhere in the codebase.
        capabilities=[build_instrumentation()],
    )
    register_document_search_tools(agent)
    return agent


def _analysis_run_context(project_path: str | None) -> CopilotRunContext:
    """Build the run context that the native documentation search reads.

    The request is a placeholder, as in ``agent_plan/builder.py``: the analysis
    has no AG-UI run, and only ``project_path`` is read. To be revisited with
    the Copilot v2 context-management work.
    """
    return CopilotRunContext(
        request=RunRequest(
            thread_id="training-error-analysis",
            run_id=uuid.uuid4().hex,
            messages=(),
        ),
        project_path=project_path,
    )


def _map_runtime_event(event: object) -> CopilotOutput | None:
    if isinstance(event, PartStartEvent) and isinstance(event.part, TextPart):
        return (
            CopilotTextContent(content=event.part.content)
            if event.part.content
            else None
        )
    if isinstance(event, PartDeltaEvent) and isinstance(event.delta, TextPartDelta):
        delta = event.delta.content_delta
        return CopilotTextContent(content=delta) if delta else None
    if isinstance(event, FunctionToolCallEvent):
        return MCPToolCall(
            tool_name=event.part.tool_name, status=MCPToolCallStatus.CALLED
        )
    if isinstance(event, FunctionToolResultEvent):
        status = (
            MCPToolCallStatus.COMPLETED
            if isinstance(event.part, ToolReturnPart)
            else MCPToolCallStatus.FAILED
        )
        return MCPToolCall(tool_name=event.part.tool_name, status=status)
    return None
